// 回到明确报告地、取得当前接收资格并做完原工时后，任务才引用政治唯一报告收据终结。
#include "envoy_task_report_rules.hpp"
#include <limits>
namespace hanmo::resident {
namespace {
// 每次政治完工回调都读取当前同候选的真实Action与双方接触，不借开工时的旧epoch。
class CompletingReport final:public TaskEnvoyReportContactRead {
public:
    CompletingReport(const CommonStore& c,const TaskState& t,const EnvoyTaskState& e,const InteractionState& i,const InteractionCatalog& catalog,const InteractionAccess& access):common_(c),tasks_(t),envoy_(e),interaction_(i),catalog_(catalog),access_(access){}
    Outcome<EnvoyReportContactProof> envoy_report_contact(const StableId& task,const StableId& action,Integer tick)const override{return read_envoy_report_contact(common_,tasks_,envoy_,interaction_,catalog_,access_,task,action,tick);}
private:
    const CommonStore& common_;const TaskState& tasks_;const EnvoyTaskState& envoy_;const InteractionState& interaction_;const InteractionCatalog& catalog_;const InteractionAccess& access_;
};
}
Outcome<EnvoyReportQuote> preview_envoy_report(const CommonStore& common,const TaskState& tasks,const EnvoyTaskState& envoy,const InteractionState& interaction,const InteractionCatalog& catalog,const InteractionAccess& access,const DiplomaticMissionRead& missions,const DiplomacyPresentationRead& presentations,const StableId& actor_id,const StableId& task_id,const StableId& provider,Integer revision,const EnvoyReportAuthorization& authorize){
    if(revision!=common.revision())return {false,{},common_failure("StaleWorldRevision").error};if(envoy.version!=2)return {false,{},common_failure("EnvoyReportVersionRequired").error};
    const auto* task=tasks.tasks.find(task_id);if(!task||task->assignee!=actor_id)return {false,{},common_failure("TaskNotKnown").error};if(task->status!="ready")return {false,{},common_failure("EnvoyReportNotAvailable",task_id).error};EnvoyTaskRead read(common,tasks,envoy,missions,presentations);auto source=read.envoy_task_source(task_id);if(!source.ok)return {false,{},source.error};const auto* contract=envoy.envoy_contracts.find(task_id);const auto& a=source.value.acceptance;
    if(task->status!="ready"||!a.return_report_required||!source.value.delivery||source.value.completion||contract->action)return {false,{},common_failure("EnvoyReportNotAvailable",task_id).error};if(!authorize)return {false,{},common_failure("MissingEnvoyReportAuthorityService",task_id,ErrorKind::internal).error};
    auto original=missions.diplomatic_mission_source(a.mission_authority_fact_id);if(!original.ok)return {false,{},original.error};const auto work=original.value.report_work_ticks;if(work<1)return {false,{},common_failure("InvalidEnvoyReportWork",task_id,ErrorKind::internal).error};if(common.tick()>std::numeric_limits<Integer>::max()-work)return {false,{},common_failure("EnvoyReportDurationOverflow",task_id).error};
    auto contact=preview_face_to_face_contact(common,interaction,catalog,access,actor_id,provider);if(!contact.ok)return {false,{},contact.error};if(contact.value.session_actor_id!=actor_id||contact.value.context.provider_actor_id!=provider||contact.value.context.place_id!=a.report_site_id)return {false,{},common_failure("EnvoyReportMeetingRequired",task_id).error};
    auto permit=authorize(a,*source.value.delivery,contact.value);if(!permit.ok)return {false,{},permit.error};return {true,{common.state().identity,task_id,work,std::move(contact.value)},{}};
}
Outcome<StableId> begin_envoy_report_in_candidate(CommonStore& common,const TaskState& tasks,EnvoyTaskState& envoy,const InteractionState& interaction,const InteractionCatalog& catalog,const InteractionAccess& access,const DiplomaticMissionRead& missions,const DiplomacyPresentationRead& presentations,const StableId& actor_id,const StableId& task_id,const StableId& provider,Integer revision,const EnvoyReportAuthorization& authorize){
    auto quote=preview_envoy_report(common,tasks,envoy,interaction,catalog,access,missions,presentations,actor_id,task_id,provider,revision,authorize);if(!quote.ok)return {false,{},quote.error};auto id=common.next_id("action");if(!id.ok)return id;
    ActionMutation start;start.kind=ActionMutation::Kind::insert;start.action={id.value,"envoy_report",actor_id,{actor_id,provider},common.tick(),quote.value.duration_ticks};auto changed=common.apply_action(start);if(!changed.ok)return {false,{},changed.error};for(const auto& participant:start.action.participants){ActorMutation occupied;occupied.actor_id=participant;occupied.action_id=id.value;changed=common.apply_actor(occupied);if(!changed.ok)return {false,{},changed.error};}
    auto* contract=envoy.envoy_contracts.find(task_id);contract->action=EnvoyTaskAction{id.value,EnvoyTaskActionKind::report,quote.value.contact.context};contract->pending_code.clear();return id;
}
Outcome<DiplomaticEnvoyReportAttempt> finish_envoy_report_in_candidate(CommonStore& common,TaskState& tasks,EnvoyTaskState& envoy,const InteractionState& interaction,const InteractionCatalog& catalog,const InteractionAccess& access,const DiplomaticMissionRead& missions,const DiplomacyPresentationRead& presentations,const DiplomaticEnvoyReportRead& reports,const StableId& task_id,const StableId& action_id,Integer completed_tick,const EnvoyReportCommit& receive){
    if(envoy.version!=2)return {false,{},common_failure("EnvoyReportVersionRequired").error};EnvoyTaskRead read(common,tasks,envoy,missions,presentations,reports);auto source=read.envoy_task_source(task_id);if(!source.ok)return {false,{},source.error};
    if(source.value.completion){const auto& final=*source.value.completion;if(final.result!=EnvoyTaskResult::completed||final.report_action_id!=action_id||final.completed_tick!=completed_tick||!final.diplomatic_report_fact_id)return {false,{},common_failure("EnvoyAlreadyCompleted",task_id).error};return {true,{DiplomaticEnvoyReportAttemptKind::reported,*final.diplomatic_report_fact_id,{},{}},{}};}
    if(!receive)return {false,{},common_failure("MissingEnvoyReportService",task_id,ErrorKind::internal).error};CompletingReport contact(common,tasks,envoy,interaction,catalog,access);auto proof=contact.envoy_report_contact(task_id,action_id,completed_tick);if(!proof.ok)return {false,{},proof.error};auto original=missions.diplomatic_mission_source(source.value.acceptance.mission_authority_fact_id);if(!original.ok)return {false,{},original.error};const auto* action=common.action(action_id);if(original.value.report_work_ticks<1||completed_tick-action->start_tick<original.value.report_work_ticks)return {false,{},common_failure("EnvoyReportWorkIncomplete",task_id,ErrorKind::internal).error};
    auto attempted=receive(contact,task_id,action_id,completed_tick);if(!attempted.ok)return attempted;const auto& attempt=attempted.value;
    if(attempt.kind!=DiplomaticEnvoyReportAttemptKind::reported){if(!attempt.report_fact_id.empty()||attempt.code.empty()||(attempt.kind==DiplomaticEnvoyReportAttemptKind::renew_contact&&attempt.continuity)||(attempt.kind==DiplomaticEnvoyReportAttemptKind::responsibility_blocked&&(!attempt.continuity||attempt.continuity->kind==DiplomaticMissionContinuityKind::continue_work))||(attempt.kind!=DiplomaticEnvoyReportAttemptKind::renew_contact&&attempt.kind!=DiplomaticEnvoyReportAttemptKind::responsibility_blocked))return {false,{},common_failure("InvalidEnvoyReportAttempt",task_id,ErrorKind::internal).error};return attempted;}
    if(attempt.report_fact_id.empty()||!attempt.code.empty()||attempt.continuity)return {false,{},common_failure("InvalidEnvoyReportAttempt",task_id,ErrorKind::internal).error};auto id=common.next_id("envoy_complete");if(!id.ok)return {false,{},id.error};const auto& a=source.value.acceptance;EnvoyTaskCompletion final;final.fact_id=id.value;final.task_id=task_id;final.contract_id=a.contract_id;final.acceptance_fact_id=a.fact_id;final.delivery_fact_id=source.value.delivery->fact_id;final.report_action_id=action_id;final.completed_tick=completed_tick;final.diplomatic_report_fact_id=attempt.report_fact_id;
    auto wrote=common.append_fact({final.fact_id,"envoy_task_completed","tasks"});if(!wrote.ok)return {false,{},wrote.error};auto* contract=envoy.envoy_contracts.find(task_id);auto* task=tasks.tasks.find(task_id);contract->completion=std::move(final);contract->action.reset();contract->pending_code.clear();task->status="success";task->settlement_id=id.value;task->reported_tick=completed_tick;auto verified=read.envoy_task_source(task_id);if(!verified.ok)return {false,{},verified.error};return attempted;
}
}
